template <class Mutex>
class unique_lock {
public:
    explicit unique_lock(Mutex& m, defer_lock_t t) noexcept;  // Defers locking; no lock acquired in constructor
    explicit unique_lock(Mutex& m, try_to_lock_t t);  // Attempts to lock using try_lock()
    explicit unique_lock(Mutex& m, adopt_lock_t t) noexcept;  // Assumes lock is already held
    // Implementation notes: The compiler uses SFINAE or partial specialization to handle these tags, ensuring the correct constructor is selected at compile-time, with runtime effects only for actual locking operations.

code_example:
#include <mutex>
#include <iostream>
int main() {
    std::mutex mtx;
    std::unique_lock<std::mutex> lk1(mtx, std::defer_lock);  // Tag: defer_lock_t; lock not acquired
    lk1.lock();  // Manual lock call required
    std::cout << "Lock acquired via defer_lock" << std::endl;
    lk1.unlock();

    std::unique_lock<std::mutex> lk2(mtx, std::try_to_lock);  // Tag: try_to_lock_t; attempts lock
    if (lk2.owns_lock()) {
        std::cout << "Lock acquired via try_to_lock" << std::endl;
    } else {
        std::cout << "Failed to acquire lock" << std::endl;
    }
    return 0;
}
